'use strict';
const defaults={eyes:0,mouth:0,hair:0,costume:0,hairColor:'#242b3d',costumeColor:'#667af0',skinColor:'#efbf9b'};
let config={...defaults};try{const old=JSON.parse(localStorage.getItem('moon-character'));if(valid(old))config=old}catch{}
const canvas=document.querySelector('#canvas'),ctx=canvas.getContext('2d');let walking=true,facing=1,speed=1,phase=0,last=0,showRig=false;
const groups=[['eyes','ดวงตา','EYES',['มั่นใจ','กลมโต','ผ่อนคลาย']],['mouth','ปาก','MOUTH',['ยิ้ม','นิ่ง','ร่าเริง']],['hair','ทรงผม','HAIR',['แสกข้าง','ผมตั้ง','บ๊อบ']],['hairColor','สีผม','HAIR COLOR',['#242b3d','#725043','#f3d78e','#d8e1ee','#a585dd']],['costume','ชุด','COSTUME',['นักผจญภัย','นักรบ','ลำลอง']],['costumeColor','สีชุด','OUTFIT COLOR',['#667af0','#7156a6','#549f88','#bd5a5c','#d7b465']],['skinColor','สีผิว','SKIN TONE',['#efbf9b','#f6d7bf','#ca936a','#8d5d48']]];
function valid(v){return v&&Object.keys(defaults).every(k=>typeof defaults[k]==='number'?Number.isInteger(v[k])&&v[k]>=0&&v[k]<3:typeof v[k]==='string'&&/^#[0-9a-f]{6}$/i.test(v[k]))}
function controls(){document.querySelector('#controls').innerHTML=groups.map(([key,label,en,options])=>`<div class="control"><div class="control-title"><b>${label}</b><small>${en}</small></div><div class="${key.endsWith('Color')?'colors':'choices'}">${options.map((value,i)=>key.endsWith('Color')?`<button aria-label="${label} ${value}" aria-pressed="${config[key]===value}" class="swatch ${config[key]===value?'active':''}" style="background:${value}" data-key="${key}" data-color="${value}"></button>`:`<button class="choice ${config[key]===i?'active':''}" aria-pressed="${config[key]===i}" data-key="${key}" data-index="${i}">${value}</button>`).join('')}${key.endsWith('Color')?`<input aria-label="เลือก${label}" type="color" value="${config[key]}" data-key="${key}">`:''}</div></div>`).join('')}
controls();document.querySelector('#controls').addEventListener('click',e=>{const b=e.target.closest('button[data-key]');if(!b)return;config[b.dataset.key]=b.dataset.color??Number(b.dataset.index);controls();persist()});document.querySelector('#controls').addEventListener('input',e=>{if(e.target.type==='color'){config[e.target.dataset.key]=e.target.value;persist()}});
function status(s){document.querySelector('#status').textContent=s}function persist(){try{localStorage.setItem('moon-character',JSON.stringify(config))}catch{status('เบราว์เซอร์นี้ไม่อนุญาตให้บันทึกในเครื่อง')}}
function path(c,d,fill,stroke='#182132',width=3){c.beginPath();for(const [op,...args] of d)c[op](...args);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.lineJoin='round';c.lineCap='round';c.stroke()}}
function ellipse(c,x,y,rx,ry,fill,stroke=null,w=3){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=w;c.stroke()}}
function rect(c,x,y,w,h,r,fill,stroke='#182132'){c.beginPath();c.roundRect(x,y,w,h,r);c.fillStyle=fill;c.fill();if(stroke){c.lineWidth=3;c.strokeStyle=stroke;c.stroke()}}
function joint(c){if(!showRig)return;ellipse(c,0,0,5,5,'#bcff68','#182132',1)}
function segment(c,x,y,angle,draw){c.save();c.translate(x,y);c.rotate(angle);draw();joint(c);c.restore()}
function line(c,x1,y1,x2,y2,color,w=3){c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.strokeStyle=color;c.lineWidth=w;c.lineCap='round';c.stroke()}
function arm(c,side,a,back){segment(c,side*46,-12,a,()=>{rect(c,-15,0,30,66,13,config.costume===2?config.skinColor:config.costumeColor);if(config.costume===1)rect(c,-21,-6,42,30,9,'#a4b4cc');segment(c,0,57,Math.max(0,-side*Math.sin(phase))*.3,()=>{rect(c,-12,0,24,54,10,config.skinColor);if(config.costume!==2)rect(c,-14,25,28,28,7,'#263246');ellipse(c,0,58,14,17,config.skinColor,'#182132')});if(showRig)line(c,0,0,0,57,'#bcff68',2)});}
function leg(c,x,a,bend){segment(c,x,100,a,()=>{rect(c,-19,0,38,73,13,config.costume===2?'#34425b':'#293548');if(config.costume===1)rect(c,-18,34,36,32,8,'#9cabc2');segment(c,0,64,bend,()=>{rect(c,-16,0,32,66,10,'#293548');rect(c,-18,37,36,34,7,config.costume===2?'#d5deec':'#3e4e67');path(c,[['moveTo',-18,58],['lineTo',15,58],['quadraticCurveTo',26,65,35,71],['quadraticCurveTo',39,82,26,83],['lineTo',-20,83],['closePath']],'#1c2535');line(c,-18,79,31,79,'#64748c',4);if(showRig)line(c,0,0,0,65,'#bcff68',2)});if(showRig)line(c,0,0,0,64,'#bcff68',2)})}
function hairBack(c){if(config.hair===2)path(c,[['moveTo',-73,-71],['quadraticCurveTo',-99,-120,-72,-167],['quadraticCurveTo',0,-225,72,-170],['quadraticCurveTo',99,-110,74,-47],['lineTo',52,-57],['lineTo',-51,-57],['closePath']],config.hairColor)}
function head(c){hairBack(c);rect(c,-17,-75,34,40,9,config.skinColor);ellipse(c,-70,-115,12,17,config.skinColor,'#182132');ellipse(c,70,-115,12,17,config.skinColor,'#182132');path(c,[['moveTo',-70,-148],['bezierCurveTo',-68,-202,66,-203,70,-148],['lineTo',67,-108],['bezierCurveTo',63,-60,-61,-60,-67,-108],['closePath']],config.skinColor);ellipse(c,-43,-105,12,6,'#d58c7d');ellipse(c,43,-105,12,6,'#d58c7d');for(const side of [-1,1]){const x=side*29;if(config.eyes===2){path(c,[['moveTo',x-12,-127],['quadraticCurveTo',x,-137,x+12,-127]],null,'#24304b',4)}else{ellipse(c,x,-130,config.eyes===1?12:13,config.eyes===1?17:11,'#fffaf3','#29364a',2);ellipse(c,x+2,-130,6,config.eyes===1?12:9,'#516c95');ellipse(c,x+3,-130,3,7,'#17243a');ellipse(c,x+4,-135,2,3,'white');line(c,x-13,-145,x+12,-148,'#29364a',4)}}if(config.mouth===0)path(c,[['moveTo',-10,-96],['quadraticCurveTo',0,-86,12,-97]],null,'#754a47',3);if(config.mouth===1)line(c,-8,-94,9,-94,'#754a47',3);if(config.mouth===2){path(c,[['moveTo',-13,-99],['lineTo',14,-99],['quadraticCurveTo',12,-77,-10,-88],['closePath']],'#613e49');line(c,-8,-96,10,-96,'white',4)}
const h=config.hairColor;if(config.hair===0)path(c,[['moveTo',-75,-116],['lineTo',-82,-157],['quadraticCurveTo',-85,-210,-25,-211],['quadraticCurveTo',45,-222,75,-177],['lineTo',79,-128],['lineTo',58,-146],['lineTo',42,-181],['quadraticCurveTo',5,-141,-35,-139],['lineTo',-18,-163],['lineTo',-59,-129],['lineTo',-60,-161],['closePath']],h);if(config.hair===1)path(c,[['moveTo',-72,-116],['lineTo',-85,-163],['lineTo',-64,-159],['lineTo',-66,-199],['lineTo',-44,-187],['lineTo',-24,-223],['lineTo',-6,-198],['lineTo',21,-221],['lineTo',34,-197],['lineTo',60,-207],['lineTo',62,-179],['lineTo',82,-172],['lineTo',71,-117],['lineTo',48,-159],['lineTo',22,-165],['lineTo',6,-148],['lineTo',-11,-173],['lineTo',-49,-151],['closePath']],h);if(config.hair===2)path(c,[['moveTo',-79,-110],['lineTo',-77,-161],['quadraticCurveTo',-66,-212,0,-207],['quadraticCurveTo',71,-210,78,-153],['lineTo',78,-106],['lineTo',59,-132],['lineTo',49,-163],['lineTo',8,-146],['lineTo',-2,-165],['lineTo',-50,-143],['lineTo',-63,-115],['closePath']],h);path(c,[['moveTo',-52,-184],['quadraticCurveTo',-20,-205,15,-195]],null,'#ffffff25',7);if(showRig)line(c,0,0,0,-118,'#bcff68',2)}
function torso(c){const color=config.costumeColor;path(c,[['moveTo',-42,-30],['lineTo',-19,-44],['quadraticCurveTo',0,-27,19,-44],['lineTo',42,-30],['lineTo',49,44],['lineTo',41,110],['lineTo',-41,110],['lineTo',-49,44],['closePath']],color);if(config.costume===0){path(c,[['moveTo',-42,-28],['lineTo',-21,-40],['lineTo',-6,8],['lineTo',-15,100],['lineTo',-43,109],['closePath']],'#263349');path(c,[['moveTo',42,-28],['lineTo',21,-40],['lineTo',6,8],['lineTo',15,100],['lineTo',43,109],['closePath']],'#263349');line(c,-5,9,27,58,'#d5c196',6)}if(config.costume===1){path(c,[['moveTo',-35,-27],['lineTo',0,-13],['lineTo',35,-27],['lineTo',32,44],['lineTo',0,59],['lineTo',-32,44],['closePath']],'#a3b5d1');path(c,[['moveTo',0,-3],['lineTo',15,19],['lineTo',0,40],['lineTo',-15,19],['closePath']],color);line(c,-26,48,0,61,'#60728c',4);line(c,26,48,0,61,'#60728c',4)}if(config.costume===2){path(c,[['moveTo',-19,-40],['quadraticCurveTo',0,-7,19,-40]],null,'#182132',6);line(c,-9,-12,-9,24,'#dae3f3',2);line(c,9,-12,9,24,'#dae3f3',2);rect(c,-24,45,48,24,5,color);line(c,-18,52,18,52,'#ffffff40',2)}else{rect(c,-44,76,88,15,4,'#1b2535');rect(c,-9,74,18,19,3,'#d8c08e')}if(showRig){line(c,0,-20,0,100,'#bcff68',2);line(c,-46,-12,46,-12,'#bcff68',2);line(c,-22,100,22,100,'#bcff68',2)}}
function draw(c,w,h,transparent=false){c.clearRect(0,0,w,h);c.save();c.translate(w/2,h*.69);const scale=Math.min(w/800,h/760)*1.15;c.scale(scale,scale);if(!transparent){ellipse(c,0,257,138,16,'#00000038');c.strokeStyle='#63738c45';c.lineWidth=1;c.beginPath();c.ellipse(0,250,190,38,0,0,Math.PI*2);c.stroke()}c.scale(facing,1);const s=walking?Math.sin(phase):0,bob=walking?Math.cos(phase*2)*3:0;c.translate(0,bob);arm(c,-1,s*.55,true);leg(c,-22,-s*.48,walking?Math.max(0,-s)*.65:0);leg(c,22,s*.48,walking?Math.max(0,s)*.65:0);torso(c);arm(c,1,-s*.55,false);segment(c,0,-28,s*.025,()=>head(c));c.restore()}
function frame(t){if(last&&walking)phase+=Math.min((t-last)/1000,.05)*speed*6;last=t;draw(ctx,canvas.width,canvas.height);requestAnimationFrame(frame)}requestAnimationFrame(frame);
document.querySelector('#play').onclick=()=>{walking=!walking;if(!walking)phase=0;document.querySelector('#play').textContent=walking?'Ⅱ หยุดเดิน':'▶ เดิน';document.querySelector('#poseLabel').textContent=walking?'WALK CYCLE':'IDLE POSE'};
document.querySelector('#direction').onclick=()=>{facing*=-1;document.querySelector('#direction').textContent=facing===1?'↔ หันซ้าย':'↔ หันขวา'};document.querySelector('#speed').oninput=e=>{speed=Number(e.target.value);document.querySelector('#speedValue').value=speed.toFixed(1)+'×'};document.querySelector('#rig').onchange=e=>showRig=e.target.checked;
document.querySelector('#save').onclick=()=>{persist();status('บันทึกตัวละครไว้ในเครื่องแล้ว')};document.querySelector('#reset').onclick=()=>{config={...defaults};controls();persist();status('คืนค่าเริ่มต้นแล้ว')};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelector('#png').onclick=()=>{const out=document.createElement('canvas');out.width=800;out.height=760;const wasRig=showRig;showRig=false;draw(out.getContext('2d'),800,760,true);showRig=wasRig;out.toBlob(blob=>{if(blob){download(blob,'moon-character.png');status('ส่งออก PNG พื้นหลังโปร่งใสแล้ว')}})};
document.querySelector('#json').onclick=()=>{download(new Blob([JSON.stringify({version:1,appearance:config,rig:{parts:['head','torso','leftUpperArm','leftForearm','leftHand','rightUpperArm','rightForearm','rightHand','leftThigh','leftShin','leftShoe','rightThigh','rightShin','rightShoe','hair'],animation:'walk'},speed},null,2)],{type:'application/json'}),'moon-character.json');status('ส่งออกค่าตัวละคร JSON แล้ว')};
document.querySelector('#load').onclick=()=>document.querySelector('#file').click();document.querySelector('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!valid(data.appearance))throw Error();config={...defaults,...Object.fromEntries(Object.keys(defaults).map(k=>[k,data.appearance[k]]))};controls();persist();status('นำเข้าตัวละครแล้ว')}catch{status('ไฟล์ไม่ถูกต้อง กรุณาใช้ JSON ที่ส่งออกจากแอปนี้')}e.target.value=''};
